    13→// DepositContractAddress returns the deposit contract address for the given chain.
    14→func DepositContractAddress() (string, error) {
    15→	address := params.BeaconConfig().DepositContractAddress
    16→	if address == "" {
    17→		return "", errors.New("valid deposit contract is required")
    18→	}
    19→
    20→	if !common.IsHexAddress(address) {
    21→		return "", errors.New("invalid deposit contract address given: " + address)
    22→	}
    23→	return address, nil
    24→}
    25→
    26→func (s *Service) processDeposit(ctx context.Context, eth1Data *ethpb.Eth1Data, deposit *ethpb.Deposit) error {
    27→	var err error
    28→	if err := s.preGenesisState.SetEth1Data(eth1Data); err != nil {
    29→		return err
    30→	}
    31→	// preGenesisState is always a genesis state ( phase 0 ) and so state version does not need to be checked here for post electra deposit processing
    32→	beaconState, err := altair.ProcessPreGenesisDeposits(ctx, s.preGenesisState, []*ethpb.Deposit{deposit})
    33→	if err != nil {
    34→		return errors.Wrap(err, "could not process pre-genesis deposits")
    35→	}
    36→	if beaconState != nil && !beaconState.IsNil() {
    37→		s.preGenesisState = beaconState
    38→	}
    39→	return nil
    40→}
