   258→// It consists of the necessary components for constructing data column sidecars
   259→// objects to gossip through p2p.
   260→// It is introduced in Fulu network upgrade.
   261→message BlobsBundleV2 {
   262→  repeated bytes kzg_commitments = 1 [
   263→    (ethereum.eth.ext.ssz_size) = "?,48",
   264→    (ethereum.eth.ext.ssz_max) = "max_blob_commitments.size"
   265→  ];
   266→
   267→  repeated bytes proofs = 2 [
   268→    (ethereum.eth.ext.ssz_size) = "?,48",
   269→    (ethereum.eth.ext.ssz_max) = "max_cell_proofs_length.size" // Changed in EIP-7594
   270→  ];
   271→
   272→  repeated bytes blobs = 3 [
   273→    (ethereum.eth.ext.ssz_size) = "?,blob.size",
   274→    (ethereum.eth.ext.ssz_max) = "max_blob_commitments.size"
   275→  ];
   276→}
   277→
   278→// Blob contains the data that is to be committed on chain.
   279→message Blob {
   280→  // The blob bytes.
   281→  bytes data = 1 [ (ethereum.eth.ext.ssz_size) = "blob.size" ];
   282→}
   283→
   284→// BlobAndProofV2 consists of the blob and the cell proofs for each cell in the blob.
   285→message BlobAndProof {
   286→  bytes blob = 1 [ (ethereum.eth.ext.ssz_size) = "blob.size" ];
   287→  bytes kzg_proof = 2 [ (ethereum.eth.ext.ssz_size) = "48" ];
   288→}
   289→
   290→// BlobAndProofV2 consists of the blob and the cell proofs for each cell in the blob.
   291→// It is introduced in Fulu network upgrade.
   292→message BlobAndProofV2 {
   293→  bytes blob = 1 [ (ethereum.eth.ext.ssz_size) = "blob.size" ];
   294→  repeated bytes kzg_proofs = 2 [ 
   295→    (ethereum.eth.ext.ssz_size) = "48",
   296→    (ethereum.eth.ext.ssz_max) = "max_cell_proofs_length.size"
   297→  ];
   298→}

