    30→message WithdrawalRequest {
    31→  // The execution address receiving the funds
    32→  bytes source_address = 1 [ (ethereum.eth.ext.ssz_size) = "20" ];
    33→
    34→  // 48 byte BLS public key of the validator.
    35→  bytes validator_pubkey = 2 [ (ethereum.eth.ext.ssz_size) = "48" ];
    36→
    37→  // Deposit amount in gwei.
    38→  uint64 amount = 3;
    39→}
    40→
    41→// DepositRequest is the message from the execution layer to trigger the deposit
    42→// of a validator's balance to its balance new in Electra
    43→message DepositRequest {
    44→  bytes pubkey = 1 [ (ethereum.eth.ext.ssz_size) = "48" ];
    45→  bytes withdrawal_credentials = 2 [ (ethereum.eth.ext.ssz_size) = "32" ];
    46→  uint64 amount = 3;
    47→  bytes signature = 4 [ (ethereum.eth.ext.ssz_size) = "96" ];
    48→  uint64 index = 5;
    49→}
