    51→// ConsolidationRequest is the message from the execution layer to trigger the
    52→// consolidation of one validator to another validator.
    53→message ConsolidationRequest {
    54→  // Source address of account which originated the request.
    55→  bytes source_address = 1 [ (ethereum.eth.ext.ssz_size) = "20" ];
    56→  // Funds will be moved from this public key.
    57→  bytes source_pubkey = 2 [ (ethereum.eth.ext.ssz_size) = "48" ];
    58→  // Funds will be moved to this public key.
    59→  bytes target_pubkey = 3 [ (ethereum.eth.ext.ssz_size) = "48" ];
    60→}
