   211→  bytes head_block_hash = 1 [ (ethereum.eth.ext.ssz_size) = "32" ];
   212→  bytes safe_block_hash = 2 [ (ethereum.eth.ext.ssz_size) = "32" ];
   213→  bytes finalized_block_hash = 3 [ (ethereum.eth.ext.ssz_size) = "32" ];
   214→}
   215→
   216→// The withdrawal receipt with the recipient address and amount withdrawn
   217→message Withdrawal {
   218→  // Withdrawal index for accounting purposes
   219→  uint64 index = 1;
   220→
   221→  // Validator index for the withdrawal
   222→  uint64 validator_index = 2
   223→      [ (ethereum.eth.ext.cast_type) =
   224→            "github.com/OffchainLabs/prysm/v6/consensus-types/"
   225→            "primitives.ValidatorIndex" ];
   226→
   227→  // The execution address receiving the funds
   228→  bytes address = 3 [ (ethereum.eth.ext.ssz_size) = "20" ];
   229→
   230→  // The withdrawn amount in Gwei
   231→  uint64 amount = 4;
   232→}
   233→
   234→// BlobsBundle is retrieved through engine-api from the execution layer client.
   235→// It consists of the necessary components for constructing blob sidecars
   236→// objects to gossip through p2p.
   237→message BlobsBundle {
   238→  // The KZG commitments of the blobs.
   239→  repeated bytes kzg_commitments = 1 [
   240→    (ethereum.eth.ext.ssz_size) = "?,48",
   241→    (ethereum.eth.ext.ssz_max) = "max_blob_commitments.size"
   242→  ];
   243→
   244→  // The proofs of the blobs.
   245→  repeated bytes proofs = 2 [
   246→    (ethereum.eth.ext.ssz_size) = "?,48",
   247→    (ethereum.eth.ext.ssz_max) = "max_blob_commitments.size"
   248→  ];
   249→
   250→  // The blobs itself.
   251→  repeated bytes blobs = 3 [
   252→    (ethereum.eth.ext.ssz_size) = "?,blob.size",
   253→    (ethereum.eth.ext.ssz_max) = "max_blob_commitments.size"
   254→  ];
   255→}
   256→
   257→// BlobsBundleV2 is retrieved through engine-api from the execution layer client.
   258→// It consists of the necessary components for constructing data column sidecars
   259→// objects to gossip through p2p.
   260→// It is introduced in Fulu network upgrade.
   261→message BlobsBundleV2 {
   262→  repeated bytes kzg_commitments = 1 [
   263→    (ethereum.eth.ext.ssz_size) = "?,48",
   264→    (ethereum.eth.ext.ssz_max) = "max_blob_commitments.size"
   265→  ];
   266→
   267→  repeated bytes proofs = 2 [
   268→    (ethereum.eth.ext.ssz_size) = "?,48",
   269→    (ethereum.eth.ext.ssz_max) = "max_cell_proofs_length.size" // Changed in EIP-7594
   270→  ];
   271→
   272→  repeated bytes blobs = 3 [
   273→    (ethereum.eth.ext.ssz_size) = "?,blob.size",
   274→    (ethereum.eth.ext.ssz_max) = "max_blob_commitments.size"
   275→  ];
   276→}
   277→
   278→// Blob contains the data that is to be committed on chain.
   279→message Blob {
   280→  // The blob bytes.
   281→  bytes data = 1 [ (ethereum.eth.ext.ssz_size) = "blob.size" ];
   282→}
   283→
   284→// BlobAndProofV2 consists of the blob and the cell proofs for each cell in the blob.
   285→message BlobAndProof {
   286→  bytes blob = 1 [ (ethereum.eth.ext.ssz_size) = "blob.size" ];
   287→  bytes kzg_proof = 2 [ (ethereum.eth.ext.ssz_size) = "48" ];
   288→}
   289→
   290→// BlobAndProofV2 consists of the blob and the cell proofs for each cell in the blob.
   291→// It is introduced in Fulu network upgrade.
   292→message BlobAndProofV2 {
   293→  bytes blob = 1 [ (ethereum.eth.ext.ssz_size) = "blob.size" ];
   294→  repeated bytes kzg_proofs = 2 [ 
   295→    (ethereum.eth.ext.ssz_size) = "48",
   296→    (ethereum.eth.ext.ssz_max) = "max_cell_proofs_length.size"
   297→  ];
   298→}

