    50→func ProcessOperations(ctx context.Context, st state.BeaconState, block interfaces.ReadOnlyBeaconBlock) (state.BeaconState, error) {
    51→	var err error
    52→
    53→	// 6110 validations are in VerifyOperationLengths
    54→	bb := block.Body()
    55→	// Electra extends the altair operations.
    56→	exitInfo := v.ExitInformation(st)
    57→	if err := helpers.UpdateTotalActiveBalanceCache(st, exitInfo.TotalActiveBalance); err != nil {
    58→		return nil, errors.Wrap(err, "could not update total active balance cache")
    59→	}
    60→	st, err = ProcessProposerSlashings(ctx, st, bb.ProposerSlashings(), exitInfo)
    61→	if err != nil {
    62→		return nil, errors.Wrap(err, "could not process altair proposer slashing")
    63→	}
    64→	st, err = ProcessAttesterSlashings(ctx, st, bb.AttesterSlashings(), exitInfo)
    65→	if err != nil {
    66→		return nil, errors.Wrap(err, "could not process altair attester slashing")
    67→	}
    68→	st, err = ProcessAttestationsNoVerifySignature(ctx, st, block)
    69→	if err != nil {
    70→		return nil, errors.Wrap(err, "could not process altair attestation")
    71→	}
    72→	if _, err := ProcessDeposits(ctx, st, bb.Deposits()); err != nil { // new in electra
    73→		return nil, errors.Wrap(err, "could not process altair deposit")
    74→	}
    75→	st, err = ProcessVoluntaryExits(ctx, st, bb.VoluntaryExits(), exitInfo)
    76→	if err != nil {
    77→		return nil, errors.Wrap(err, "could not process voluntary exits")
    78→	}
    79→	st, err = ProcessBLSToExecutionChanges(st, block)
    80→	if err != nil {
    81→		return nil, errors.Wrap(err, "could not process bls-to-execution changes")
    82→	}
    83→	// new in electra
    84→	requests, err := bb.ExecutionRequests()
    85→	if err != nil {
    86→		return nil, errors.Wrap(err, "could not get execution requests")
    87→	}
    88→	for _, d := range requests.Deposits {
    89→		if d == nil {
    90→			return nil, errors.New("nil deposit request")
    91→		}
    92→	}
    93→	st, err = ProcessDepositRequests(ctx, st, requests.Deposits)
    94→	if err != nil {
    95→		return nil, execReqErr{errors.Wrap(err, "could not process deposit requests")}
    96→	}
    97→	for _, w := range requests.Withdrawals {
    98→		if w == nil {
    99→			return nil, errors.New("nil withdrawal request")
   100→		}
   101→	}
   102→	st, err = ProcessWithdrawalRequests(ctx, st, requests.Withdrawals)
   103→	if err != nil {
   104→		return nil, execReqErr{errors.Wrap(err, "could not process withdrawal requests")}
   105→	}
   106→	for _, c := range requests.Consolidations {
   107→		if c == nil {
   108→			return nil, errors.New("nil consolidation request")
   109→		}
   110→	}
   111→	if err := ProcessConsolidationRequests(ctx, st, requests.Consolidations); err != nil {
   112→		return nil, execReqErr{errors.Wrap(err, "could not process consolidation requests")}
   113→	}
   114→	return st, nil
   115→}
