    25→
    26→// IsMergeTransitionComplete returns true if the transition to Bellatrix has completed.
    27→// Meaning the payload header in beacon state is not `ExecutionPayloadHeader()` (i.e. not empty).
    28→//
    29→// Spec code:
    30→// def is_merge_transition_complete(state: BeaconState) -> bool:
    31→//
    32→//	return state.latest_execution_payload_header != ExecutionPayloadHeader()
    33→func IsMergeTransitionComplete(st state.BeaconState) (bool, error) {
    34→	if st == nil {
    35→		return false, errors.New("nil state")
    36→	}
    37→	if IsPreBellatrixVersion(st.Version()) {
    38→		return false, nil
    39→	}
    40→	if st.Version() > version.Bellatrix {
    41→		return true, nil
    42→	}
    43→	h, err := st.LatestExecutionPayloadHeader()
    44→	if err != nil {
    45→		return false, err
    46→	}
    47→	isEmpty, err := blocks.IsEmptyExecutionData(h)
    48→	if err != nil {
    49→		return false, err
    50→	}
    51→	return !isEmpty, nil
    52→}
    53→
    54→// IsExecutionBlock returns whether the block has a non-empty ExecutionPayload.
    55→//
    56→// Spec code:
    57→// def is_execution_block(block: ReadOnlyBeaconBlock) -> bool:
    58→//
    59→//	return block.body.execution_payload != ExecutionPayload()
    60→func IsExecutionBlock(body interfaces.ReadOnlyBeaconBlockBody) (bool, error) {
    61→	if body == nil {
    62→		return false, errors.New("nil block body")
    63→	}
    64→	if body.Version() >= version.Capella {
    65→		return true, nil
    66→	}
    67→	payload, err := body.Execution()
    68→	switch {
    69→	case errors.Is(err, consensus_types.ErrUnsupportedField):
    70→		return false, nil
    71→	case err != nil:
    72→		return false, err
    73→	default:
    74→	}
    75→	isEmpty, err := blocks.IsEmptyExecutionData(payload)
    76→	if err != nil {
    77→		return false, err
    78→	}
    79→	return !isEmpty, nil
    80→}
    81→
    82→// IsExecutionEnabled returns true if the beacon chain can begin executing.
    83→// Meaning the payload header is beacon state is non-empty or the payload in block body is non-empty.
    84→//
    85→// Spec code:
    86→// def is_execution_enabled(state: BeaconState, body: ReadOnlyBeaconBlockBody) -> bool:
    87→//
    88→//	return is_merge_block(state, body) or is_merge_complete(state)
    89→func IsExecutionEnabled(st state.BeaconState, body interfaces.ReadOnlyBeaconBlockBody) (bool, error) {
    90→	if st == nil || body == nil {
    91→		return false, errors.New("nil state or block body")
    92→	}
    93→	if IsPreBellatrixVersion(st.Version()) {
    94→		return false, nil
    95→	}
    96→	header, err := st.LatestExecutionPayloadHeader()
    97→	if err != nil {
    98→		return false, err
    99→	}
   100→	return IsExecutionEnabledUsingHeader(header, body)
   101→}
   102→
   103→// IsExecutionEnabledUsingHeader returns true if the execution is enabled using post processed payload header and block body.
   104→// This is an optimized version of IsExecutionEnabled where beacon state is not required as an argument.
   105→func IsExecutionEnabledUsingHeader(header interfaces.ExecutionData, body interfaces.ReadOnlyBeaconBlockBody) (bool, error) {
   106→	isEmpty, err := blocks.IsEmptyExecutionData(header)
   107→	if err != nil {
   108→		return false, err
   109→	}
   110→	if !isEmpty {
   111→		return true, nil
   112→	}
   113→	return IsExecutionBlock(body)
   114→}
   115→
   116→// IsPreBellatrixVersion returns true if input version is before bellatrix fork.
   117→func IsPreBellatrixVersion(v int) bool {
   118→	return v < version.Bellatrix
   119→}
