   327→func reviewGasLimit(gasLimit validator.Uint64) validator.Uint64 {
   328→	// sets gas limit to default if not defined or set to 0
   329→	if gasLimit == 0 {
   330→		return validator.Uint64(params.BeaconConfig().DefaultBuilderGasLimit)
   331→	}
   332→
   333→	// Warning for ranges that might be problematic
   334→	defaultGasLimit := params.BeaconConfig().DefaultBuilderGasLimit
   335→	// If gas limit is very low (below 10% of default), warn about potential issues
   336→	if gasLimit <= validator.Uint64(defaultGasLimit/10) {
   337→		log.Warnf("Gas limit %d is very low compared to default %d, which may cause transactions to fail", gasLimit, defaultGasLimit)
   338→	}
   339→	// If gas limit is very high (above 150% of default), warn about potential block propagation issues
   340→	if gasLimit > validator.Uint64(defaultGasLimit*3/2) {
   341→		log.Warnf("Gas limit %d is very high compared to default %d", gasLimit, defaultGasLimit)
   342→	}
   343→
   344→	return gasLimit
   345→}
